interface ChatEnvelope {
  messageId: string;
  roomId: string;
  senderId: string;
  text: string;
  sentAt: number;
}

interface ClientSocket {
  readonly socketId: string;
  emit(event: string, payload: ChatEnvelope): void;
}

interface PubSubClient {
  subscribe(channel: string, handler: (envelope: ChatEnvelope) => void): void;
  publish(channel: string, envelope: ChatEnvelope): Promise<void>;
}

/**
 * One stateless gateway node in the cluster. Multiple instances of this
 * class run behind a load balancer; `pubsub` is how they stay in sync.
 */
export class ChatGateway {
  private readonly nodeId: string;
  private readonly pubsub: PubSubClient;
  // Sockets currently attached to THIS node, keyed by roomId.
  private readonly localSockets: Map<string, Set<ClientSocket>> = new Map();

  constructor(nodeId: string, pubsub: PubSubClient) {
    this.nodeId = nodeId;
    this.pubsub = pubsub;
  }

  /** Called the first time this node has a local subscriber for a room. */
  private ensureSubscribed(roomId: string): void {
    if (this.localSockets.has(roomId)) return;
    this.localSockets.set(roomId, new Set());
    // On startup (per-room, lazily) the node registers a subscription handler:
    // every node, including the one that originated the message, receives
    // the envelope from the channel and hands it to its local clients.
    this.pubsub.subscribe(this.channelFor(roomId), (envelope) =>
      this.onBackplaneMessage(envelope),
    );
  }

  registerSocket(roomId: string, socket: ClientSocket): void {
    this.ensureSubscribed(roomId);
    this.localSockets.get(roomId)!.add(socket);
  }

  unregisterSocket(roomId: string, socket: ClientSocket): void {
    this.localSockets.get(roomId)?.delete(socket);
  }

  /**
   * Handles an outbound chat message from a client attached to this node.
   */
  async handleSend(roomId: string, senderId: string, text: string): Promise<void> {
    const envelope: ChatEnvelope = {
      messageId: `${this.nodeId}-${Date.now()}-${Math.random().toString(36).slice(2)}`,
      roomId,
      senderId,
      text,
      sentAt: Date.now(),
    };

    // Optimistic local emit so nearby clients see it instantly, without
    // waiting on a round-trip through the backplane.
    this.deliverLocal(envelope);

    // Fan the message out to every other node (and, incidentally, back to
    // this one) via the shared pub/sub channel for the room.
    await this.pubsub.publish(this.channelFor(roomId), envelope);
  }

  /**
   * Subscription callback for this node's channel. This is meant to be the
   * single place messages get handed to local sockets.
   */
  private onBackplaneMessage(envelope: ChatEnvelope): void {
    this.deliverLocal(envelope);
  }

  private deliverLocal(envelope: ChatEnvelope): void {
    const sockets = this.localSockets.get(envelope.roomId);
    if (!sockets || sockets.size === 0) return;
    for (const socket of sockets) {
      socket.emit('message', envelope);
    }
  }

  private channelFor(roomId: string): string {
    return `chat:room:${roomId}`;
  }
}
